WITH pattern_union_r AS (
SELECT 'Order' AS start_type, toString(test_integration.orders_fk.order_id) as start_id, toString(test_integration.customers_fk.customer_id) as end_id, 'Customer' AS end_type, ['PLACED_BY'] as path_relationships, ['{}'] as rel_properties, formatRowNoNewline('JSONEachRow', test_integration.orders_fk.order_date AS _s_order_date, test_integration.orders_fk.order_id AS _s_order_id, test_integration.orders_fk.total_amount AS _s_total_amount) as start_properties, formatRowNoNewline('JSONEachRow', test_integration.customers_fk.customer_id AS _e_customer_id, test_integration.customers_fk.email AS _e_email, test_integration.customers_fk.name AS _e_name) as end_properties FROM test_integration.orders_fk INNER JOIN test_integration.customers_fk ON test_integration.customers_fk.customer_id = test_integration.orders_fk.customer_id
UNION ALL
SELECT 'Customer' AS start_type, toString(test_integration.customers_fk.customer_id) as start_id, toString(test_integration.orders_fk.order_id) as end_id, 'Order' AS end_type, ['PLACED_BY'] as path_relationships, ['{}'] as rel_properties, formatRowNoNewline('JSONEachRow', test_integration.customers_fk.customer_id AS _s_customer_id, test_integration.customers_fk.email AS _s_email, test_integration.customers_fk.name AS _s_name) as start_properties, formatRowNoNewline('JSONEachRow', test_integration.orders_fk.order_date AS _e_order_date, test_integration.orders_fk.order_id AS _e_order_id, test_integration.orders_fk.total_amount AS _e_total_amount) as end_properties FROM test_integration.orders_fk INNER JOIN test_integration.customers_fk ON test_integration.customers_fk.customer_id = test_integration.orders_fk.customer_id
)
SELECT 
      count(*) AS "count(*)"
FROM pattern_union_r AS r
WHERE r.start_id = r.end_id AND r.start_type = r.end_type
